import{_ as e,c as r,o,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Настройки логов","description":"","frontmatter":{"title":"Настройки логов"},"headers":[],"relativePath":"ru/logs/settings.md","filePath":"ru/logs/settings.md"}'),n={name:"ru/logs/settings.md"};function a(g,t,d,i,c,h){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="настроики-логов" tabindex="-1">Настройки логов <a class="header-anchor" href="#настроики-логов" aria-label="Permalink to &quot;Настройки логов&quot;">​</a></h1><p>В <strong>Options → Logs</strong> собраны настройки вкладки <a href="./general.html">Logs</a>. Блоки идут так: <strong>Search Settings</strong>, <strong>Logs and limits</strong>, <strong>Ignore list</strong>, <strong>Data masking</strong>, <strong>Export</strong>. Изменения применяются сразу.</p><hr><h2 id="search-settings" tabindex="-1">Search Settings <a class="header-anchor" href="#search-settings" aria-label="Permalink to &quot;Search Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Флажок</th><th>По умолчанию</th></tr></thead><tbody><tr><td><strong>Search by event name (title, component, store, URL)</strong></td><td>включён</td></tr><tr><td><strong>Search by key (payload keys and changed paths)</strong></td><td>выключен</td></tr><tr><td><strong>Search by value (payload values)</strong></td><td>выключен</td></tr></tbody></table><p>Как запрос совпадает, описано в <a href="./general.html#search">Работе с логами</a>. Если key и value оба выключены, поиск по имени всё равно работает.</p><hr><h2 id="logs-and-limits" tabindex="-1">Logs and limits <a class="header-anchor" href="#logs-and-limits" aria-label="Permalink to &quot;Logs and limits&quot;">​</a></h2><h3 id="logged-events" tabindex="-1">Logged events <a class="header-anchor" href="#logged-events" aria-label="Permalink to &quot;Logged events&quot;">​</a></h3><p>У каждой группы есть чекбокс: снятая группа не логируется совсем, уже записанные события остаются. По умолчанию включены все группы.</p><table tabindex="0"><thead><tr><th>Группа</th><th>События</th></tr></thead><tbody><tr><td><strong>Requests</strong></td><td><strong>Send request</strong> и <strong>Receive response</strong></td></tr><tr><td><strong>WebSocket</strong></td><td><strong>WebSocket open</strong>, <strong>WebSocket sent</strong>, <strong>WebSocket received</strong> и <strong>WebSocket closed</strong></td></tr><tr><td><strong>Props changes</strong></td><td><strong>Change props</strong></td></tr><tr><td><strong>Emits</strong></td><td><strong>Emit</strong></td></tr><tr><td><strong>Pinia changes</strong></td><td><strong>Change store</strong> (после повторной отметки стор начинается с нового <strong>Store snapshot</strong>)</td></tr><tr><td><strong>Store actions</strong></td><td><strong>Store action</strong></td></tr><tr><td><strong>Navigation</strong></td><td><strong>Navigation</strong></td></tr><tr><td><strong>Clicks</strong></td><td><strong>Click</strong></td></tr><tr><td><strong>JS errors</strong></td><td><strong>JS error</strong></td></tr></tbody></table><p>Число рядом с чекбоксом — сколько событий этой группы хранится сейчас. Подсказка: <strong>Currently stored</strong>. <strong>Requests</strong> не считает <strong>Receive response</strong>, единица — <strong>requests</strong>. У остальных групп единица <strong>events</strong>.</p><h3 id="data-size" tabindex="-1">Data size <a class="header-anchor" href="#data-size" aria-label="Permalink to &quot;Data size&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>По умолчанию</th><th>Диапазон</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Memory budget</strong></td><td>20 МБ</td><td>8 – 1024 МБ</td><td>Общий объём всех событий в буфере (приблизительный размер после сериализации). Сетевая запись, общая для запроса и ответа, и одинаковые тела учитываются один раз. Бинарный ответ учитывается как формат и размер, без самого файла</td></tr><tr><td><strong>Limit event size</strong></td><td>вкл.</td><td>—</td><td>Включён по умолчанию. Выключено: события хранятся целиком. Поле <strong>Max event size</strong> видно только пока флажок включён</td></tr><tr><td><strong>Max event size</strong></td><td>512 КБ</td><td>16 – 16 384 КБ</td><td>Крупные части события (снимки стора, аргументы, результаты) отбрасываются, сетевые тела обрезаются до этого размера</td></tr></tbody></table><p>При достижении бюджета памяти журнал отсекается по <strong>Navigation</strong>, и каждое событие до неё удаляется. Изменения <strong>Pinia</strong> до этой точки собираются в <strong>Store checkpoint</strong>, поэтому у оставшихся изменений сохраняются <strong>Before</strong> / <strong>After</strong>; предыдущая база и diff, из которых она собрана, удаляются (см. <a href="./general.html#how-events-are-stored">Как хранятся события</a>). Последняя навигация переписывается в снимок страницы, а если журнал всё ещё больше бюджета, удаляются самые старые из оставшихся событий. Самое новое событие сохраняется всегда, даже если одно превышает бюджет. <strong>Send request</strong> и <strong>Receive response</strong> дополнительно ограничены лимитом <strong>Maximum HTTP requests</strong> — тем же кольцом, что HTTP-строки вкладки Network (<strong>Options → Network</strong>, по умолчанию <strong>500</strong>): запрос и его ответ уходят вместе. События WebSocket ограничены лимитом <strong>Maximum WebSocket events</strong> (по умолчанию <strong>500</strong>): open, sent, received и closed считаются по одному.</p><p>Строка под полосой: <strong>Used {size} of {size} (approximate serialized size).</strong> Полоса становится оранжевой с 90 %.</p><p>Число вне диапазона округляется и прижимается к ближайшей границе. Нечисловое значение сбрасывается на значение по умолчанию. Пустое поле считается нулём и поэтому становится минимумом (8 МБ или 16 КБ). Новое значение применяется, когда поле подтверждают.</p><p><strong>Defaults</strong> в этом блоке возвращает флажки групп, бюджет, <strong>Limit event size</strong> и <strong>Max event size</strong>. Поиск, список игнорирования, маскирование и <strong>Compress report</strong> он не сбрасывает.</p><hr><h2 id="ignore-list" tabindex="-1">Ignore list <a class="header-anchor" href="#ignore-list" aria-label="Permalink to &quot;Ignore list&quot;">​</a></h2><p>Группы событий, исключённые из записи. Группа — один объект: один и тот же запрос (метод и путь), один и тот же компонент, один и тот же стор и т.д. События игнорируемых групп не записываются вовсе.</p><p>Под заголовком: <strong>These event groups are not recorded. Log again resumes one group.</strong></p><table tabindex="0"><thead><tr><th>Столбец</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>Подпись события (<strong>Send request</strong>, <strong>Change store</strong>, <strong>JS error</strong> и остальные)</td></tr><tr><td><strong>Object</strong></td><td>Сохранённый ключ группы: URL, компонент, стор, сообщение и т.д.</td></tr></tbody></table><p>Меню строки — только <strong>Log again</strong>. <strong>Log all again</strong> напротив заголовка очищает список и недоступна, когда он пуст. Пустая таблица: <em>No ignored objects</em>. Клик по строке ничего не делает. Карточки деталей нет.</p><p>Индикатор <strong>ignored</strong> на панели вкладки <a href="./general.html">Logs</a> открывает эту таблицу. При пустом списке он скрыт.</p><hr><h2 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking {#data-masking}&quot;">​</a></h2><p>Значения маскируются <strong>в момент записи события</strong>, поэтому не попадают ни в интерфейс <strong>Logs</strong>, ни в экспорт.</p><p>Под заголовком: <strong>Values are masked when an event is captured, so they never reach the Logs view or exports.</strong></p><p>Оба флажка подписаны <strong>Mask sensitive data</strong>.</p><ul><li>Первый включает маскирование. По умолчанию он включён. Пока он выключен, список ключей приглушён, и записанные значения сохраняются как есть.</li><li>Второй стоит сразу под ним и недоступен, пока первый выключен. По умолчанию он включён. В любом тексте от 8 символов он маскирует <strong>JWT</strong> (<code>[MASKED JWT]</code>), учётные данные <strong>Bearer</strong> / <strong>Basic</strong> / <strong>Token</strong> (<code>Bearer [MASKED]</code>) и номера карт (<code>[MASKED CARD]</code>). Отдельной подписи у этого поведения нет.</li></ul><p>Заголовок списка ключей — <strong>Key contains</strong>. Пустая таблица: <em>No keys — only value patterns are masked</em>. Подсказка поля: <strong>Key fragment, e.g. accessCode</strong>. <strong>Add</strong> или <strong>Enter</strong> обрезает фрагмент. Пустое значение: <strong>Key cannot be empty</strong>. Тот же фрагмент без учёта регистра: <strong>This key is already in the list</strong>. Меню строки — <strong>Delete</strong>. Клик по строке ничего не делает.</p><p>Ключи по умолчанию: <code>password</code>, <code>passwd</code>, <code>pwd</code>, <code>secret</code>, <code>token</code>, <code>authorization</code>, <code>cookie</code>, <code>apikey</code>, <code>sessionid</code>, <code>privatekey</code>, <code>creditcard</code>, <code>cardnumber</code>, <code>cvv</code>, <code>cvc</code>, <code>ssn</code>, <code>otp</code>.</p><p>Сравнение ключей не учитывает регистр и разделители (<code>api_key</code>, <code>api-key</code> и <code>apiKey</code> — одно и то же). Фрагменты из <strong>4 букв и короче</strong> должны совпадать с целым словом, поэтому <code>pwd</code> или <code>otp</code> не маскируют посторонние ключи.</p><p><strong>Defaults</strong> напротив заголовка возвращает оба флажка и список ключей.</p><p>Значения чувствительных ключей заменяются на <code>[MASKED]</code>. Номера карт проверяются алгоритмом Луна.</p><hr><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export {#export}&quot;">​</a></h2><p><strong>Compress report</strong> включён по умолчанию. Пока браузер умеет сжимать, подсказка пишет <strong>The HTML report is several times smaller. Needs Chrome / Edge 80+, Firefox 113+ or Safari 16.4+.</strong> Тогда JSON событий хранится в файле как gzip в base64. В браузере, который сжимать не умеет, флажок недоступен, а подсказка пишет <strong>Not supported in this browser. Needs Chrome / Edge 80+, Firefox 113+ or Safari 16.4+.</strong> Что лежит в файле, описано в <a href="./export.html">Экспорте</a>.</p><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./general.html">Работа с логами</a></li><li><a href="./export.html">Экспорт</a></li><li><a href="/qa-tools/docs/ru/options/settings_management.html">Менеджер настроек</a></li></ul>',42)])])}const m=e(n,[["render",a]]);export{p as __pageData,m as default};
